import java.util.Scanner;

public class ArtanSiraUcSayi {

	public static void main(String[] args) {

		Scanner okuyucu = new Scanner(System.in);

		System.out.print("Birinci sayiyi girin: ");
		int x = okuyucu.nextInt();

		System.out.print("ikinci sayiyi girin: ");
		int y = okuyucu.nextInt();

		System.out.print("Ucuncu sayiyi girin: ");
		int z = okuyucu.nextInt();

		okuyucu.close();

		// Uc degeri diziye alip kabarcik siralamasi ile diziyoruz,
		// boylece uzun if-else zincirine gerek kalmiyor
		int[] veriler = { x, y, z };
		for (int i = 0; i < veriler.length - 1; i++) {
			for (int j = 0; j < veriler.length - 1 - i; j++) {
				if (veriler[j] > veriler[j + 1]) {
					int temp = veriler[j];
					veriler[j] = veriler[j + 1];
					veriler[j + 1] = temp;
				}
			}
		}

		System.out.println("Artan sirayla: " + veriler[0] + ", " + veriler[1] + ", " + veriler[2]);
	}
}
