import java.util.Scanner;

/*
 * Bu program girilen bir para tutarini, mumkun olan en az sayida bozuk
 * para (25, 10, 5 ve 1 kurusluklar) kullanarak parcalara ayirir.
 */

public class ParaBozma {

	public static void main(String[] args) {

		Scanner okuyucu = new Scanner(System.in);

		System.out.print("Bozuk para miktarini giriniz: ");
		double kalanTutar = okuyucu.nextDouble();
		okuyucu.close();

		// Ondalikli sayilarda yuvarlama hatasi olmamasi icin kucuk bir pay ekliyoruz
		kalanTutar += 0.001;

		int[] adetler = new int[4];
		double[] birimler = { 0.25, 0.10, 0.05, 0.01 };

		// Buyukten kucuge dogru her bozuk para biriminden kac tane cikacagini buluyoruz
		for (int i = 0; i < birimler.length; i++) {
			adetler[i] = (int) (kalanTutar / birimler[i]);
			kalanTutar = kalanTutar % birimler[i];
		}

		System.out.println("25 Kurus: " + adetler[0] + " tane.");
		System.out.println("10 Kurus: " + adetler[1] + " tane.");
		System.out.println("5  Kurus: " + adetler[2] + " tane.");
		System.out.println("1  Kurus: " + adetler[3] + " tane.");
	}
}
