package datatypes;

public class FloatVeDoubleOrnegi {

    public static void main(String[] args) {

        // float degerler "f" son ekiyle, double degerler ise dogrudan yazilir
        float birinciDeger = 123.45f;
        double ikinciDeger = 678.90;

        System.out.println("Float Sayi: " + birinciDeger);
        System.out.println("Double Sayi: " + ikinciDeger);

        // double -> float donusumu daralttigi icin acik cast gerektirir
        float daraltilmis = (float) ikinciDeger;
        // float -> double donusumu ise otomatik (genisletme) gerceklesir
        double genisletilmis = birinciDeger;

        System.out.println("Float'tan Double'a Donusum: " + daraltilmis);
        System.out.println("Double'dan Float'a Donusum: " + genisletilmis);

        // Karisik tip aritmetigi: sonuc turu islemin genisligine gore degisir
        double toplamSonuc = birinciDeger + ikinciDeger;
        float carpimSonuc = birinciDeger * (float) ikinciDeger;
        double farkSonuc = ikinciDeger - birinciDeger;
        float bolumSonuc = birinciDeger / (float) ikinciDeger;

        System.out.println("Toplama Sonucu (float + double): " + toplamSonuc);
        System.out.println("Carpma Sonucu (float * double): " + carpimSonuc);
        System.out.println("Cikarma Sonucu (double - float): " + farkSonuc);
        System.out.println("Bolme Sonucu (float / double): " + bolumSonuc);

        // Her iki turun de sinir degerleri
        System.out.println("Float Min Degeri: " + Float.MIN_VALUE);
        System.out.println("Float Max Degeri: " + Float.MAX_VALUE);
        System.out.println("Double Min Degeri: " + Double.MIN_VALUE);
        System.out.println("Double Max Degeri: " + Double.MAX_VALUE);
    }
}
