package datatypes;

public class ShortVeriTuruOrnegi {

    public static void main(String[] args) {

        // iki short degeri ile temel islemler yapiliyor
        short a = 300;
        short b = 500;

        // short + short sonucu int'e genisledigi icin geri cast ediyoruz
        short toplamSonuc = (short) (a + b);
        System.out.println("Toplam: " + toplamSonuc);

        short farkSonuc = (short) (b - a);
        System.out.println("Fark: " + farkSonuc);

        short carpimSonuc = (short) (a * b);
        System.out.println("Carpim: " + carpimSonuc);

        short bolumSonuc = (short) (b / a);
        System.out.println("Bolum: " + bolumSonuc);

        short kalanSonuc = (short) (b % a);
        System.out.println("Kalan: " + kalanSonuc);

        // Bir arttirma ve bir azaltma ornegi
        short arttirilmisA = (short) (a + 1);
        short azaltilmisB = (short) (b - 1);

        System.out.println("Arttirilmis Sayi1: " + arttirilmisA);
        System.out.println("Azaltilmis Sayi2: " + azaltilmisB);

        // Pozitif/negatif kontrolu
        String isaret = (a > 0) ? "pozitif bir degerdir." : "negatif bir degerdir.";
        System.out.println("Sayi1 " + isaret);

        // short turunun sinir degerleri
        System.out.println("\nShort veri turunun minimum degeri: " + Short.MIN_VALUE);
        System.out.println("Short veri turunun maksimum degeri: " + Short.MAX_VALUE);

        short ustSinir = Short.MAX_VALUE;
        short altSinir = Short.MIN_VALUE;

        // Sinir degerleri arasindaki farkin hesaplanmasi
        short sinirFarki = (short) (ustSinir - altSinir);
        System.out.println("Short veri turunun max ve min degeri arasindaki fark: " + sinirFarki);

        // Ek bir toplama ornegi daha
        short c = 1500;
        short d = 1200;
        short sonToplam = (short) (c + d);
        System.out.println("Yeni toplam: " + sonToplam);
    }
}
