package eamples;

import java.util.Scanner; // reads the candidate number typed by the user

public class AsalSayiMi {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        // Ask the user which value should be checked for primality.
        System.out.println("Bir sayi giriniz:");
        int candidate = input.nextInt();

        // Track whether we ever discover a divisor other than 1 and itself.
        boolean hasDivisor = false;

        // Walk upward from 2 and stop as soon as a divisor turns up,
        // using a while-loop instead of the classic for-loop.
        int probe = 2;
        while (probe < candidate) {
            if (candidate % probe == 0) {
                hasDivisor = true;
                System.out.println("Sayi asal degil.");
                break;
            }
            probe++;
        }

        // No divisor was found while scanning, so the number is prime.
        if (!hasDivisor) {
            System.out.println("Sayi asal.");
        }

        input.close();
    }
}
