package eamples;

import java.util.Scanner;

public class Faktoriyel {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.println("Bir sayi giriniz:");
        int n = input.nextInt();

        System.out.print(n);

        // Compute n! by counting down from n to 1 using a for-loop
        // (original used a while-loop that mutated the input variable).
        int product = 1;
        for (int k = n; k > 0; k--) {
            product *= k;
        }

        System.out.println("! = " + product);

        input.close();
    }
}
