public class RakamlarToplami {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.println("Bir sayi giriniz:");
        int remaining = input.nextInt();

        // Accumulate digit sum with a do-while loop instead of a plain while-loop.
        int total = 0;
        if (remaining > 0) {
            do {
                int lastDigit = remaining % 10;
                total = total + lastDigit;
                remaining /= 10;
            } while (remaining > 0);
        }

        System.out.println("Rakamlar toplami: " + total);

        input.close();
    }
}
