package functions;
import java.util.Scanner;  // kullanici girisini okumak icin gerekli sinif

public class Fibonacci {

    // Belirtilen adete kadar Fibonacci dizisini yazdirir ve altin orani hesaplar
    void fibonacciYazdir(int adet) {

        int guncel = 0;   // her adimda hesaplanan yeni terim
        int onceki = 1;   // dizideki ilk terim
        int oncekiIkinci = 1; // dizideki ikinci terim

        // ilk iki terim sabit oldugundan direkt yazdirilir
        System.out.print("1 1 ");

        int index = 2;
        while (index < adet) {
            guncel = onceki + oncekiIkinci; // yeni terim onceki ikisinin toplami
            onceki = oncekiIkinci;          // kaydirma islemi
            oncekiIkinci = guncel;
            System.out.print(guncel + " ");
            index++;
        }

        System.out.println();

        // son iki terimin orani altin oranina yaklasir
        System.out.println("Altin oran = " + (double) ((double) oncekiIkinci / onceki));
    }

    public static void main(String[] args) {

        Scanner tarayici = new Scanner(System.in);

        System.out.println("Lutfen bir sayi giriniz");
        int girilenDeger = tarayici.nextInt();

        Fibonacci hesaplayici = new Fibonacci();
        hesaplayici.fibonacciYazdir(girilenDeger);

        tarayici.close();
    }
}
