package recursive;

public class HanoiKuleleri {

	// Cozulecek toplam disk sayisi
	public static final int DISK_ADEDI = 3;

	public static void main(String[] args) {

		hanoiCoz(DISK_ADEDI, 'A', 'C', 'B');
	}

	// Hanoi kuleleri bilmecesini ozyinelemeli olarak cozer.
	// kaynakCubuk: disklerin baslangicta durdugu cubuk
	// hedefCubuk: disklerin tasinacagi cubuk
	// araCubuk: gecici olarak kullanilacak yardimci cubuk
	public static void hanoiCoz(int diskAdedi, char kaynakCubuk, char hedefCubuk, char araCubuk) {
		// Tek disk kaldiginda dogrudan tasima yapilir
		if (diskAdedi == 1) {
			System.out.println("Disk " + diskAdedi + " direk " + kaynakCubuk + "'den direk " + hedefCubuk + "'e tasi.");
			return;
		}

		// Once ustteki (diskAdedi - 1) disk ara cubuga tasinir
		hanoiCoz(diskAdedi - 1, kaynakCubuk, araCubuk, hedefCubuk);
		// En alttaki disk hedefe tasinir
		System.out.println("Disk " + diskAdedi + " direk " + kaynakCubuk + "'den direk " + hedefCubuk + "'e tasi.");
		// Ara cubuktaki diskler hedefe tasinir
		hanoiCoz(diskAdedi - 1, araCubuk, hedefCubuk, kaynakCubuk);
	}

}
