public class CollatzDizisi {

	public static void main(String[] args) {

		Scanner girisAraci = new Scanner(System.in);
		System.out.print("Pozitif bir tam sayi giriniz: ");
		int baslangicDegeri = girisAraci.nextInt();
		girisAraci.close();

		// Gecersiz girisler icin islenmeden cikilir
		if (baslangicDegeri <= 0) {
			System.out.println("Lutfen pozitif bir tam sayi giriniz.");
			return;
		}

		StringBuilder diziMetni = new StringBuilder();
		diziMetni.append(baslangicDegeri);

		int adimSayaci = 1;
		int mevcutDeger = baslangicDegeri;

		// Deger 1'e inene kadar Collatz kuralini uygulamaya devam ediyoruz
		do {
			if (mevcutDeger % 2 == 0) {
				mevcutDeger = mevcutDeger / 2;
			} else {
				mevcutDeger = 3 * mevcutDeger + 1;
			}
			diziMetni.append(" -> ").append(mevcutDeger);
			adimSayaci++;
		} while (mevcutDeger != 1);

		System.out.println("Collatz Dizisi:");
		System.out.print(diziMetni);
		System.out.println("\nCollatz dizisinin uzunlugu: " + adimSayaci);
	}
}
