package inheritance;

/*
 * Extends the basic HesapMakinesi with more advanced math:
 * square root, power, natural logarithm and factorial, each
 * implemented manually instead of relying on java.lang.Math.
 */
public class GelismisHesapMakinesi extends HesapMakinesi {

    public GelismisHesapMakinesi() {
        super(); // reuse the parent's default construction
    }

    // Approximates the square root using Newton-Raphson iteration.
    public double kareKok(double deger) {
        if (deger < 0) {
            throw new IllegalArgumentException("Negatif sayilarin karekoku hesaplanamaz.");
        }
        double tahmin = deger;
        double tolerans = 0.0001; // acceptable margin of error
        while (true) {
            double sonrakiTahmin = (tahmin + deger / tahmin) / 2;
            if (Math.abs(tahmin - sonrakiTahmin) < tolerans) {
                break; // converged closely enough
            }
            tahmin = sonrakiTahmin;
        }
        return tahmin;
    }

    // Raises taban to the given power via repeated multiplication.
    public double us(double taban, double kuvvet) {
        if (kuvvet < 0) {
            return 1 / us(taban, -kuvvet); // handle negative exponents via reciprocal
        }
        double birikenSonuc = 1.0;
        for (int sayac = 0; sayac < kuvvet; sayac++) {
            birikenSonuc = birikenSonuc * taban;
        }
        return birikenSonuc;
    }

    // Computes a natural-log-like value using the Gregory-Leibniz series.
    public double logaritma(double deger) {
        if (deger <= 0) {
            throw new IllegalArgumentException("Pozitif sayi girmelisiniz");
        }
        double oran = (deger - 1) / (deger + 1);
        double toplamSeri = 0.0;
        for (int terim = 1; terim < 1000; terim += 2) {
            toplamSeri = toplamSeri + (1.0 / terim) * us(oran, terim);
        }
        return 2 * toplamSeri;
    }

    // Computes the factorial iteratively; 0! is defined as 1.
    public double faktoriyel(double deger) {
        if (deger == 0) {
            return 1;
        }
        double sonuc = 1;
        for (int i = 1; i <= deger; i++) {
            sonuc = sonuc * i;
        }
        return sonuc;
    }

    public static void main(String[] args) {
        GelismisHesapMakinesi makine = new GelismisHesapMakinesi();

        double birinciSayi = 16.0;
        double ikinciSayi = 2.0;
        double ucuncuSayi = 5.0;

        System.out.println("Karekok Hesaplama:");
        System.out.println(birinciSayi + "'in karekoku: " + makine.kareKok(birinciSayi));

        System.out.println("\nUs Alma:");
        System.out.println(ikinciSayi + "'nin " + ucuncuSayi + " ussu: " + makine.us(ikinciSayi, ucuncuSayi));

        System.out.println("\nLogaritma Hesaplama:");
        System.out.println(birinciSayi + "'in logaritmasi: " + makine.logaritma(birinciSayi));

        System.out.println("\nFaktoriyel Hesaplama:");
        System.out.println(ucuncuSayi + "'in faktoriyeli: " + makine.faktoriyel(ucuncuSayi));
    }
}
