package inheritance;

/*
 * Simple four-operation calculator that remembers its last
 * computed result in an internal memory slot.
 */
public class HesapMakinesi {

    // Stores the outcome of the most recent operation.
    private double sonMemoriDeger;

    public double topla(int a, int b) {
        sonMemoriDeger = a + b;
        return sonMemoriDeger;
    }

    public double cikart(int a, int b) {
        sonMemoriDeger = a - b;
        return sonMemoriDeger;
    }

    public double carp(int a, int b) {
        sonMemoriDeger = a * b;
        return sonMemoriDeger;
    }

    public double bol(int a, int b) {
        if (b == 0) {
            System.out.println("Sifira bolme hatasi!");
            return Double.NaN;
        }
        sonMemoriDeger = (double) a / b;
        return sonMemoriDeger;
    }

    // Exposes whatever value memory currently holds.
    public double hafizayiGoruntule() {
        return sonMemoriDeger;
    }

    // Resets the memory back to zero.
    public void hafizayiSifirla() {
        sonMemoriDeger = 0;
    }

    public static void main(String[] args) {
        HesapMakinesi makine = new HesapMakinesi();

        double toplamSonuc = makine.topla(5, 3);
        System.out.println("Toplama Sonucu: " + toplamSonuc);

        System.out.println("Hafiza: " + makine.hafizayiGoruntule());

        makine.hafizayiSifirla();
        System.out.println("Hafiza sifirlandiktan sonra: " + makine.hafizayiGoruntule());

        toplamSonuc = makine.cikart(10, 4);
        System.out.println("Cikarma Sonucu: " + toplamSonuc);
    }
}
