package polymorphism;

/**
 * Round figure defined purely by its radius.
 */
public class Cember extends Sekil {

    private double r;

    public Cember(double r) {
        super("Cember");
        this.r = r;
    }

    public double getYaricap() {
        return r;
    }

    public void setYaricap(double r) {
        this.r = r;
    }

    @Override
    public double alanHesapla() {
        return Math.PI * r * r;
    }

    @Override
    public double cevreHesapla() {
        return 2.0 * Math.PI * r;
    }

    @Override
    public void ciz() {
        System.out.println("Cember ciziliyor: Yaricap " + r);
    }
}
