package array;

/*
 * Reverses an int array in place and reports its smallest value.
 */
public class DiziyiTersCevirme {

    public static void main(String[] args) {
        int[] sayilar = {5, 2, 8, 1, 9, 4, 7};

        cevir(sayilar);

        System.out.println("Ters Cevrilmis Dizi Elemanlari:");
        goster(sayilar);

        int kucuk = enKucuguBul(sayilar);
        System.out.println("\nDizideki Minimum Eleman: " + kucuk);
    }

    public static void cevir(int[] sayilar) {
        int sol = 0;
        int sag = sayilar.length - 1;

        while (sol < sag) {
            int gecici = sayilar[sol];
            sayilar[sol] = sayilar[sag];
            sayilar[sag] = gecici;
            sol++;
            sag--;
        }
    }

    public static void goster(int[] sayilar) {
        for (int deger : sayilar) {
            System.out.print(deger + " ");
        }
        System.out.println();
    }

    public static int enKucuguBul(int[] sayilar) {
        int enKucuk = sayilar[0];
        for (int i = 1; i < sayilar.length; i++) {
            if (sayilar[i] < enKucuk) {
                enKucuk = sayilar[i];
            }
        }
        return enKucuk;
    }
}
