package twodimensional;
import java.util.Scanner;

public class TicTacToe {

	private static final int SIZE = 3;
	private static final char EMPTY_CELL = ' ';

	public static void main(String[] args) {

		char[][] grid = new char[SIZE][SIZE];
		char activePlayer = 'X'; // X always opens the game
		boolean playing = true;

		resetGrid(grid);

		while (playing) {
			printGrid(grid);
			readMove(grid, activePlayer);
			playing = checkStatus(grid, activePlayer);
			activePlayer = swapPlayer(activePlayer);
		}
		printGrid(grid);
	}

	// Fills every cell with the empty marker
	private static void resetGrid(char[][] grid) {
		for (int r = 0; r < SIZE; r++) {
			for (int c = 0; c < SIZE; c++) {
				grid[r][c] = EMPTY_CELL;
			}
		}
	}

	// Clears the terminal and draws the current board state
	private static void printGrid(char[][] grid) {
		System.out.print("\033[H\033[2J");
		System.out.flush();
		System.out.println("-------------");
		for (int r = 0; r < SIZE; r++) {
			StringBuilder rowText = new StringBuilder("| ");
			for (int c = 0; c < SIZE; c++) {
				rowText.append(grid[r][c]).append(" | ");
			}
			System.out.println(rowText);
			System.out.println("-------------");
		}
	}

	// Prompts the current player until a legal cell is chosen, then marks it
	private static void readMove(char[][] grid, char player) {
		Scanner input = new Scanner(System.in);
		int rowChoice;
		int colChoice;
		do {
			System.out.print("Sira " + player + " oyuncusunda. Satir ve sutun secin (1-3): ");
			rowChoice = input.nextInt() - 1;
			colChoice = input.nextInt() - 1;
		} while (isOutOfRange(rowChoice) || isOutOfRange(colChoice) || grid[rowChoice][colChoice] != EMPTY_CELL);
		grid[rowChoice][colChoice] = player;
	}

	private static boolean isOutOfRange(int index) {
		return index < 0 || index > SIZE - 1;
	}

	private static char swapPlayer(char current) {
		return current == 'X' ? 'O' : 'X';
	}

	// Returns true if the game should keep going, false if it just ended
	private static boolean checkStatus(char[][] grid, char player) {
		if (hasWinningLine(grid, player)) {
			System.out.println("Tebrikler, " + player + " oyuncusu kazandi!");
			return false;
		}

		if (isFull(grid)) {
			System.out.println("Oyun berabere bitti.");
			return false;
		}
		return true;
	}

	private static boolean hasWinningLine(char[][] grid, char player) {
		for (int i = 0; i < SIZE; i++) {
			if (grid[i][0] == player && grid[i][1] == player && grid[i][2] == player) {
				return true;
			}
			if (grid[0][i] == player && grid[1][i] == player && grid[2][i] == player) {
				return true;
			}
		}
		if (grid[0][0] == player && grid[1][1] == player && grid[2][2] == player) {
			return true;
		}
		if (grid[0][2] == player && grid[1][1] == player && grid[2][0] == player) {
			return true;
		}
		return false;
	}

	private static boolean isFull(char[][] grid) {
		for (int r = 0; r < SIZE; r++) {
			for (int c = 0; c < SIZE; c++) {
				if (grid[r][c] == EMPTY_CELL) {
					return false;
				}
			}
		}
		return true;
	}
}
