package checked;

import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.FileWriter;
import java.io.IOException;

public class DosyaOkumaHatasi {

    public static void main(String[] args) {

        try {
            // Attempt to open the target file for reading
            FileInputStream inputStream = new FileInputStream("test.txt");

            System.out.println("Dosya icerigi:");
            int nextByte = inputStream.read();
            while (nextByte != -1) {
                System.out.print((char) nextByte);
                nextByte = inputStream.read();
            }

            inputStream.close();
            System.out.println("\nDosya basariyla okundu.");

        } catch (FileNotFoundException missingFileEx) {
            // Raised when the requested file path doesn't exist
            System.out.println("Dosya bulunamadi: " + missingFileEx.getMessage());
            System.out.println("Lutfen dosyanin adini veya yolunu kontrol edin.");
        } catch (IOException ioEx) {
            // Any other I/O failure while reading
            System.out.println("Dosya okunurken bir hata olustu: " + ioEx.getMessage());
        } finally {
            // Always runs, regardless of whether an exception occurred
            System.out.println("Islem tamamlandi.");
        }

        appendToFile("test.txt", "Bu dosyaya yazilan yeni bir satirdir.");
    }

    /**
     * Appends a line of text to the given file.
     * @param targetFile name of the file to write into
     * @param content text to append
     */
    public static void appendToFile(String targetFile, String content) {
        try {
            FileWriter writer = new FileWriter(targetFile, true); // append mode
            writer.write("\n" + content);
            writer.close();
            System.out.println("Dosyaya veri basariyla yazildi.");
        } catch (IOException writeEx) {
            System.out.println("Dosyaya yazilirken bir hata olustu: " + writeEx.getMessage());
        }
    }
}
