import java.net.*;
import java.io.*;
import java.util.Scanner;

/*
 * Minimal socket-based chat client. Connects to a local chat server,
 * relays whatever the user types, and prints the echoed response.
 */

public class ChatIstemci {

    public static void main(String[] args) throws IOException {
        try (Socket connection = new Socket("localhost", 8000)) {

            DataInputStream fromServer = new DataInputStream(connection.getInputStream());
            DataOutputStream toServer = new DataOutputStream(connection.getOutputStream());

            try (Scanner keyboard = new Scanner(System.in)) {
                while (true) {
                    String outgoing = keyboard.nextLine();
                    toServer.writeUTF(outgoing);

                    String incoming = fromServer.readUTF();
                    System.out.println(incoming);
                }
            }
        }
    }
}
