import java.io.File;
import java.io.FileNotFoundException;
import java.util.Scanner;

/**
 * Reads arithmetic expressions from a text file, one per line, and
 * prints the evaluated result for each valid entry.
 */
public class HesapMakinesiScanner {

    private static final String KAYNAK_DOSYA = "islemler.txt";

    public static void main(String[] args) {
        File girdi = new File(KAYNAK_DOSYA);

        try (Scanner tarayici = new Scanner(girdi)) {
            System.out.println("Hesap Makinesi - Dosyadan Okuma");

            int satirNo = 0;
            while (tarayici.hasNextLine()) {
                satirNo++;
                String hamSatir = tarayici.nextLine();
                islemSatiriniIsle(hamSatir, satirNo);
            }
        } catch (FileNotFoundException hata) {
            System.out.println("Dosya bulunamadi: " + hata.getMessage());
        }
    }

    /** Bir satiri parcalayip aritmetik islemi cozumler ve sonucu basar. */
    private static void islemSatiriniIsle(String satir, int satirNo) {
        String[] token = satir.split(" ");

        if (token.length != 3) {
            System.out.println("Gecersiz islem! Lutfen dogru formatta islem girin (ornek: 10 + 5).");
            return;
        }

        try {
            int solTaraf = Integer.parseInt(token[0]);
            int sagTaraf = Integer.parseInt(token[2]);
            char operatorKarakteri = token[1].charAt(0);

            Integer sonuc = hesapla(solTaraf, sagTaraf, operatorKarakteri);
            if (sonuc != null) {
                System.out.println(solTaraf + " " + operatorKarakteri + " " + sagTaraf + " = " + sonuc);
            }
        } catch (NumberFormatException ayristirmaHatasi) {
            System.out.println("Sayilari parse ederken bir hata olustu: " + ayristirmaHatasi.getMessage());
        }
    }

    /** Verilen operatore gore iki tam sayi arasinda islem yapar. Basarisizsa null doner. */
    private static Integer hesapla(int a, int b, char op) {
        switch (op) {
            case '+':
                return a + b;
            case '-':
                return a - b;
            case '*':
                return a * b;
            case '/':
                if (b == 0) {
                    System.out.println("Hata: Sifira bolme yapilamaz!");
                    return null;
                }
                return a / b;
            default:
                System.out.println("Gecersiz islec! Lutfen +, -, * veya / kullanin.");
                return null;
        }
    }
}
