import javax.imageio.ImageIO;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.Scanner;

/**
 * Batch-converts every PNG/JPG image found in a user-supplied directory
 * into a scaled-down WebP copy, keeping the original aspect ratio.
 */
public class PNGToWebPDonusturucu {

    private static final int HEDEF_GENISLIK_PX = 300;

    /**
     * Verilen genislige orantili sekilde yeniden olceklenmis bir kopya uretir.
     */
    public static BufferedImage olcekle(BufferedImage kaynak, int istenenGenislik) {
        int kaynakGenislik = kaynak.getWidth();
        int kaynakYukseklik = kaynak.getHeight();

        double oran = (double) istenenGenislik / kaynakGenislik;
        int hesaplananYukseklik = (int) (oran * kaynakYukseklik);

        BufferedImage sonuc = new BufferedImage(istenenGenislik, hesaplananYukseklik, kaynak.getType());
        Graphics2D cizici = sonuc.createGraphics();
        try {
            cizici.drawImage(kaynak, 0, 0, istenenGenislik, hesaplananYukseklik, null);
        } finally {
            cizici.dispose();
        }
        return sonuc;
    }

    /**
     * Tek bir gorsel dosyasini okuyup olcekler ve WebP olarak diske yazar.
     */
    public static void tekDosyayiDonustur(String girisYolu, String cikisYolu) throws IOException {
        BufferedImage okunanGorsel = ImageIO.read(new File(girisYolu));
        BufferedImage kucultulmus = olcekle(okunanGorsel, HEDEF_GENISLIK_PX);

        File hedefKlasor = new File(cikisYolu).getParentFile();
        if (hedefKlasor != null && !hedefKlasor.exists()) {
            Files.createDirectories(hedefKlasor.toPath());
        }

        boolean yazmaBasarili = ImageIO.write(kucultulmus, "webp", new File(cikisYolu));
        if (!yazmaBasarili) {
            throw new IOException("Gorsel WebP formatina donusturulemedi. WebP eklentisinin yuklu oldugundan emin olun.");
        }
    }

    private static boolean resimUzantisiMi(String dosyaAdi) {
        String kucukAd = dosyaAdi.toLowerCase();
        return kucukAd.endsWith(".png") || kucukAd.endsWith(".jpg");
    }

    @SuppressWarnings("resource")
    public static void main(String[] args) {
        Scanner girisOkuyucu = new Scanner(System.in);

        System.out.println("Gorsel dosyalarinin bulundugu dizin yolunu girin (PNG/JPG):");
        String yol = girisOkuyucu.nextLine();

        File hedefDizin = new File(yol);
        if (!hedefDizin.exists() || !hedefDizin.isDirectory()) {
            System.err.println("Gecersiz dizin yolu.");
            return;
        }

        File[] adaylar = hedefDizin.listFiles((dizin, ad) -> resimUzantisiMi(ad));
        if (adaylar == null || adaylar.length == 0) {
            System.out.println("Dizinde PNG veya JPG dosyasi bulunamadi.");
            return;
        }

        for (File kaynakDosya : adaylar) {
            islemUygula(kaynakDosya);
        }

        girisOkuyucu.close();
    }

    private static void islemUygula(File kaynakDosya) {
        try {
            BufferedImage gorsel = ImageIO.read(kaynakDosya);
            if (gorsel == null) {
                System.out.println("Gorsel okunamadi: " + kaynakDosya.getName());
                return;
            }

            System.out.println("Dosya: " + kaynakDosya.getName() + " | Boyutlar: "
                    + gorsel.getWidth() + "x" + gorsel.getHeight());

            String hedefDosyaYolu = kaynakDosya.getParent() + File.separator
                    + kaynakDosya.getName().replaceAll("\\.(png|jpg)$", ".webp");

            tekDosyayiDonustur(kaynakDosya.getAbsolutePath(), hedefDosyaYolu);
            System.out.println("Donusturuldu: " + hedefDosyaYolu);
        } catch (IOException hata) {
            System.err.println("Dosya islenirken hata olustu: " + kaynakDosya.getName() + " - " + hata.getMessage());
        }
    }
}
