import java.awt.BorderLayout;
import java.awt.Color;
import javax.swing.SwingUtilities;
import javax.swing.WindowConstants;
import javax.swing.JFrame;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.text.Document;

/**
 * Girilen kurus miktarini, kullanilabilecek en buyuk madeni para
 * birimlerinden en aza dogru parcalayip canli olarak raporlayan
 * kucuk bir Swing aracı.
 */
public class ParaUstuHesaplama extends JFrame {

    private static final long serialVersionUID = 1912881839758209062L;
    private static final int[] MADENI_PARA_DEGERLERI = {50, 25, 10, 5, 1};

    private final JTextField miktarKutusu = new JTextField(12);
    private final transient Document miktarBelgesi = miktarKutusu.getDocument();
    private final JTextArea sonucAlani = new JTextArea(8, 40);

    public ParaUstuHesaplama() {
        JPanel girisPaneli = new JPanel();
        girisPaneli.add(new JLabel("Miktar:"));
        girisPaneli.add(miktarKutusu);

        getContentPane().add(girisPaneli, BorderLayout.NORTH);
        getContentPane().add(new JScrollPane(sonucAlani), BorderLayout.CENTER);
        setBackground(Color.LIGHT_GRAY);
        sonucAlani.setEditable(false);

        miktarBelgesi.addDocumentListener(new DocumentListener() {
            @Override
            public void changedUpdate(DocumentEvent e) {
                sonucuYenile();
            }

            @Override
            public void insertUpdate(DocumentEvent e) {
                sonucuYenile();
            }

            @Override
            public void removeUpdate(DocumentEvent e) {
                sonucuYenile();
            }
        });
    }

    /** Metin kutusundaki degeri okuyup para ustu dagilimini yeniden hesaplar. */
    private void sonucuYenile() {
        try {
            int kalanMiktar = Integer.parseInt(miktarBelgesi.getText(0, miktarBelgesi.getLength()));
            StringBuilder cikti = new StringBuilder();
            cikti.append(kalanMiktar).append(" kurus yapmak icin kullanilacaklar:\n");

            for (int paraBirimi : MADENI_PARA_DEGERLERI) {
                int adet = kalanMiktar / paraBirimi;
                cikti.append(adet).append(' ').append(paraBirimi).append(" kurus\n");
                kalanMiktar %= paraBirimi;
            }
            sonucAlani.setText(cikti.toString());
        } catch (NumberFormatException hata) {
            sonucAlani.setText("Tam sayi degil veya aralik disinda");
        } catch (Exception hata) {
            sonucAlani.setText(hata.toString());
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            ParaUstuHesaplama pencere = new ParaUstuHesaplama();
            pencere.setTitle("Para ustu Hesaplama");
            pencere.pack();
            pencere.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);
            pencere.setVisible(true);
        });
    }
}
