import java.awt.Graphics;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.Timer;

/** Pencere sinirlarindan sekerek hareket eden tek bir topu canlandiran ornek. */
public class SekenTop extends JPanel implements ActionListener {

    private static final long serialVersionUiD = -6368396547703393842L;

    private static final int PENCERE_GENISLIGI = 600;
    private static final int PENCERE_YUKSEKLIGI = 400;

    private static final int BASLANGIC_X_KOORDINATI = 50;
    private static final int BASLANGIC_Y_KOORDINATI = 50;

    private static final int TIMER_ARALIGI_MS = 10;
    private static final int TOP_CAPI = 50;

    private int xKoordinati;
    private int yKoordinati;
    private int xHiz;
    private int yHiz;

    public SekenTop() {
        xKoordinati = BASLANGIC_X_KOORDINATI;
        yKoordinati = BASLANGIC_Y_KOORDINATI;
        xHiz = 2;
        yHiz = 2;

        Timer kareZamanlayicisi = new Timer(TIMER_ARALIGI_MS, this);
        kareZamanlayicisi.start();
    }

    @Override
    public void paintComponent(Graphics tuval) {
        super.paintComponent(tuval);
        tuval.fillOval(xKoordinati, yKoordinati, TOP_CAPI, TOP_CAPI);
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        xKoordinati += xHiz;
        yKoordinati += yHiz;

        if (xKoordinati < 0 || xKoordinati > PENCERE_GENISLIGI - 60) {
            xHiz *= -1;
        }
        if (yKoordinati < 0 || yKoordinati > PENCERE_YUKSEKLIGI - 75) {
            yHiz *= -1;
        }

        repaint();
    }

    public static void main(String[] args) {
        JFrame pencere = new JFrame("Seken Top");
        pencere.add(new SekenTop());
        pencere.setSize(PENCERE_GENISLIGI, PENCERE_YUKSEKLIGI);
        pencere.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        pencere.setVisible(true);
    }
}
