import java.awt.Color;
import java.awt.Graphics;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

import javax.swing.JFrame;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.WindowConstants;

/** Bircok topun ayni pencere icinde birbirinden bagimsiz sekerek hareket ettigi Swing animasyonu. */
public class TopAnimasyonu extends JFrame {

    private static final long serialVersionUID = 3305372670620496856L;
    private static final int PENCERE_GENISLIGI = 600;
    private static final int PENCERE_YUKSEKLIGI = 400;
    private static final int TOP_YARICAPI = 20;
    private static final int TOP_ADEDI = 5;
    private static final int KARE_ARALIGI_MS = 30;

    private final Random rastgeleUretici = new Random();
    private final transient List<HareketliTop> toplar = new ArrayList<>();

    /** Konum ve yon bilgisi tasiyan tek bir topun modeli. */
    private static class HareketliTop {
        int x;
        int y;
        int xYonu;
        int yYonu;

        HareketliTop(int x, int y, int xYonu, int yYonu) {
            this.x = x;
            this.y = y;
            this.xYonu = xYonu;
            this.yYonu = yYonu;
        }

        void adimAt() {
            x += xYonu;
            y += yYonu;

            if (x <= 0 || x >= PENCERE_GENISLIGI - 2 * TOP_YARICAPI + 10) {
                xYonu *= -1;
            }
            if (y <= 0 || y >= PENCERE_YUKSEKLIGI - 2 * TOP_YARICAPI + 10) {
                yYonu *= -1;
            }
        }
    }

    public TopAnimasyonu() {
        setTitle("Top Animasyonu");
        setSize(PENCERE_GENISLIGI, PENCERE_YUKSEKLIGI);
        setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);

        topFiloOlustur();

        Timer kareZamanlayicisi = new Timer(KARE_ARALIGI_MS, new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                toplariIlerlet();
                repaint();
            }
        });
        kareZamanlayicisi.start();
    }

    private void topFiloOlustur() {
        for (int i = 0; i < TOP_ADEDI; i++) {
            toplar.add(new HareketliTop(
                    rastgeleUretici.nextInt(getWidth() - 2 * TOP_YARICAPI),
                    rastgeleUretici.nextInt(PENCERE_YUKSEKLIGI - 2 * TOP_YARICAPI),
                    rastgeleUretici.nextInt(5) + 1,
                    rastgeleUretici.nextInt(5) + 1));
        }
    }

    private void toplariIlerlet() {
        for (HareketliTop top : toplar) {
            top.adimAt();
        }
    }

    @Override
    public void paint(Graphics tuval) {
        super.paint(tuval);
        for (HareketliTop top : toplar) {
            tuval.setColor(Color.BLUE);
            tuval.fillOval(top.x, top.y, 2 * TOP_YARICAPI, 2 * TOP_YARICAPI);
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                new TopAnimasyonu().setVisible(true);
            }
        });
    }
}
