/**
 * Shows why a shared counter needs synchronized access when several
 * threads increment/decrement it concurrently.
 */
public class SynchronizedOrnek {

    public static void main(String[] args) {
        Tally tally = new Tally();

        Thread incrementerA = new Thread(() -> {
            for (int i = 0; i < 10000; i++) {
                tally.increase();
            }
        });

        Thread incrementerB = new Thread(() -> {
            for (int i = 0; i < 10000; i++) {
                tally.increase();
            }
        });

        Thread decrementerA = new Thread(() -> {
            for (int i = 0; i < 5000; i++) {
                tally.decrease();
            }
        });

        Thread decrementerB = new Thread(() -> {
            for (int i = 0; i < 3000; i++) {
                tally.decrease();
            }
        });

        incrementerA.start();
        incrementerB.start();
        decrementerA.start();
        decrementerB.start();

        awaitAll(incrementerA, incrementerB, decrementerA, decrementerB);

        System.out.println("Son sayac degeri: " + tally.currentValue());

        tally.reset();
        System.out.println("Sayac sifirlandi. Yeni deger: " + tally.currentValue());
    }

    private static void awaitAll(Thread... threads) {
        for (Thread t : threads) {
            try {
                t.join();
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
}

// Shared mutable resource guarded with synchronized methods
class Tally {

    private int value = 0;
    private static final int MIN_BOUND = -8000;
    private static final int MAX_BOUND = 20000;

    public synchronized void increase() {
        if (value >= MAX_BOUND) {
            System.out.println("Uyari: Sayac limiti asildi! [" + value + "]");
            return;
        }
        value++;
    }

    public synchronized void decrease() {
        if (value <= MIN_BOUND) {
            System.out.println("Uyari: Sayac zaten 0'da! [" + value + "]");
            return;
        }
        value--;
    }

    public synchronized int currentValue() {
        return value;
    }

    public synchronized void reset() {
        value = 0;
        System.out.println("Sayac sifirlandi.");
    }
}
