package tictactoe;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Font;
import java.awt.GridBagLayout;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.io.PrintWriter;
import java.net.Socket;
import java.util.Scanner;

import javax.swing.JFrame;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;

/**
 * Swing client for a two-player Tic Tac Toe game that talks to the
 * server over the small text protocol implemented in TicTacToeServer.
 */
public class TicTacToeClient {

    private static final int SERVER_PORT = 58901;

    private final JFrame window = new JFrame("Tic Tac Toe");
    private final JLabel statusLabel = new JLabel("...");

    private final Cell[] cells = new Cell[9];
    private Cell lastClickedCell;

    private final Socket connection;
    private final Scanner fromServer;
    private final PrintWriter toServer;

    public TicTacToeClient(String host) throws Exception {

        connection = new Socket(host, SERVER_PORT);
        fromServer = new Scanner(connection.getInputStream());
        toServer = new PrintWriter(connection.getOutputStream(), true);

        statusLabel.setBackground(Color.lightGray);
        window.getContentPane().add(statusLabel, BorderLayout.SOUTH);

        var grid = new JPanel();
        grid.setBackground(Color.black);
        grid.setLayout(new GridLayout(3, 3, 2, 2));
        for (int index = 0; index < cells.length; index++) {
            final int cellIndex = index;
            cells[index] = new Cell();
            cells[index].addMouseListener(new MouseAdapter() {
                @Override
                public void mousePressed(MouseEvent e) {
                    lastClickedCell = cells[cellIndex];
                    toServer.println("MOVE " + cellIndex);
                }
            });
            grid.add(cells[index]);
        }
        window.getContentPane().add(grid, BorderLayout.CENTER);
    }

    /**
     * Blocks on the input stream, updating the board and status label as
     * messages arrive from the server, until the match ends.
     */
    public void play() throws Exception {
        try {
            var greeting = fromServer.nextLine();
            var myMark = greeting.charAt(8);
            var theirMark = myMark == 'X' ? 'O' : 'X';
            window.setTitle("Tic Tac Toe: Oyuncu " + myMark);

            while (fromServer.hasNextLine()) {
                var message = fromServer.nextLine();
                if (message.startsWith("VALID_MOVE")) {
                    statusLabel.setText("Gecerli hamle, bekleyin");
                    lastClickedCell.setMark(myMark);
                    lastClickedCell.repaint();
                } else if (message.startsWith("OPPONENT_MOVED")) {
                    var position = Integer.parseInt(message.substring(15));
                    cells[position].setMark(theirMark);
                    cells[position].repaint();
                    statusLabel.setText("Rakip oynadi, sira sizde");
                } else if (message.startsWith("MESSAGE")) {
                    statusLabel.setText(message.substring(8));
                } else if (message.startsWith("VICTORY")) {
                    JOptionPane.showMessageDialog(window, "Kazandiniz!");
                    break;
                } else if (message.startsWith("DEFEAT")) {
                    JOptionPane.showMessageDialog(window, "Kaybettiniz!");
                    break;
                } else if (message.startsWith("TIE")) {
                    JOptionPane.showMessageDialog(window, "Berabere!");
                    break;
                } else if (message.startsWith("OTHER_PLAYER_LEFT")) {
                    JOptionPane.showMessageDialog(window, "Rakip oyundan ayrildi");
                    break;
                }
            }
            toServer.println("QUIT");
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            connection.close();
            window.dispose();
        }
    }

    // A single square on the board
    static class Cell extends JPanel {
        private static final long serialVersionUID = 499000751608489234L;
        private final JLabel markLabel = new JLabel();

        public Cell() {
            setBackground(Color.white);
            setLayout(new GridBagLayout());
            markLabel.setFont(new Font("Arial", Font.BOLD, 40));
            add(markLabel);
        }

        public void setMark(char mark) {
            markLabel.setForeground(mark == 'X' ? Color.BLUE : Color.RED);
            markLabel.setText(mark + "");
        }
    }

    public static void main(String[] args) throws Exception {

        TicTacToeClient client = new TicTacToeClient("localhost");
        client.window.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        client.window.setSize(320, 320);
        client.window.setVisible(true);
        client.window.setResizable(false);
        client.play();
    }
}
