package tictactoe;

import java.io.IOException;
import java.io.PrintWriter;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.Arrays;
import java.util.Scanner;
import java.util.concurrent.Executors;

/**
 * Server for a two-player Tic Tac Toe game. Pairs up incoming
 * connections two at a time and referees a single Match between them.
 */
public class TicTacToeServer {

    private static final int PORT = 58901;
    private static final int MAX_PLAYERS = 200;

    public static void main(String[] args) throws Exception {

        try (var listener = new ServerSocket(PORT)) {
            System.out.println("Tic Tac Toe Sunucusu Calisiyor...");
            var pool = Executors.newFixedThreadPool(MAX_PLAYERS);
            while (true) {
                Match match = new Match();
                pool.execute(match.new Contestant(listener.accept(), 'X'));
                pool.execute(match.new Contestant(listener.accept(), 'O'));
            }
        }
    }
}

class Match {

    // Cells 0-8; null means empty
    private final Contestant[] board = new Contestant[9];
    Contestant toMove;

    public boolean hasWinner() {
        return (board[0] != null && board[0] == board[1] && board[0] == board[2])
                || (board[3] != null && board[3] == board[4] && board[3] == board[5])
                || (board[6] != null && board[6] == board[7] && board[6] == board[8])
                || (board[0] != null && board[0] == board[3] && board[0] == board[6])
                || (board[1] != null && board[1] == board[4] && board[1] == board[7])
                || (board[2] != null && board[2] == board[5] && board[2] == board[8])
                || (board[0] != null && board[0] == board[4] && board[0] == board[8])
                || (board[2] != null && board[2] == board[4] && board[2] == board[6]);
    }

    public boolean isFull() {
        return Arrays.stream(board).allMatch(cell -> cell != null);
    }

    // Applies a move if it is legal, otherwise raises an exception describing why not
    public synchronized void applyMove(int cellIndex, Contestant contestant) {
        if (contestant != toMove) {
            throw new IllegalStateException("Sira sizde degil");
        } else if (contestant.rival == null) {
            throw new IllegalStateException("Henuz bir rakibiniz yok");
        } else if (board[cellIndex] != null) {
            throw new IllegalStateException("Bu hucre zaten dolu");
        }
        board[cellIndex] = toMove;
        toMove = toMove.rival;
    }

    /**
     * Represents one of the two connected players, holding their mark
     * and socket streams.
     */
    class Contestant implements Runnable {

        char mark;
        Contestant rival;
        Socket socket;
        Scanner incoming;
        PrintWriter outgoing;

        public Contestant(Socket socket, char mark) {
            this.socket = socket;
            this.mark = mark;
        }

        @Override
        public void run() {
            try {
                greet();
                handleCommands();
            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                if (rival != null && rival.outgoing != null) {
                    rival.outgoing.println("OTHER_PLAYER_LEFT");
                }
                try {
                    socket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        // Sets up streams and figures out whether this player moves first
        private void greet() throws IOException {
            incoming = new Scanner(socket.getInputStream());
            outgoing = new PrintWriter(socket.getOutputStream(), true);
            outgoing.println("WELCOME " + mark);
            if (mark == 'X') {
                toMove = this;
                outgoing.println("MESSAGE Rakibin baglanmasi bekleniyor...");
            } else {
                rival = toMove;
                rival.rival = this;
                rival.outgoing.println("MESSAGE Hamle sira sizde");
            }
        }

        // Reads commands from this player until QUIT or disconnect
        private void handleCommands() {
            while (incoming.hasNextLine()) {
                var command = incoming.nextLine();
                if (command.startsWith("QUIT")) {
                    return;
                } else if (command.startsWith("MOVE")) {
                    handleMove(Integer.parseInt(command.substring(5)));
                }
            }
        }

        // Attempts the requested move and reports the outcome to both players
        private void handleMove(int cellIndex) {
            try {
                applyMove(cellIndex, this);
                outgoing.println("VALID_MOVE");
                rival.outgoing.println("OPPONENT_MOVED " + cellIndex);
                if (hasWinner()) {
                    outgoing.println("VICTORY");
                    rival.outgoing.println("DEFEAT");
                } else if (isFull()) {
                    outgoing.println("TIE");
                    rival.outgoing.println("TIE");
                }
            } catch (IllegalStateException e) {
                outgoing.println("MESSAGE " + e.getMessage());
            }
        }
    }
}
