        }
        TournamentIncome tournamentIncome = new TournamentIncome(totalMatches, battle, points, players.get(index).getIncome(), players.get(index).getName());
        tournamentIncomes.set(index, tournamentIncome);
    }

    public static void cacularTournamentIncome() {
        for (TournamentIncome tournamentIncome : tournamentIncomes) {
            tournamentIncome.displayDetails();
        }
    }

