                    scanner.nextLine();
                    System.out.print("Enter number: ");
                    String number = scanner.next();
                    scanner.nextLine();
                    phoneNumbers.add(new PhoneNumber(area, number));
                    break;
                }
                case 2: {
                    System.out.print("Enter country code: ");
